  1→//! Unit tests for the offline write queue.
  2→//!
  3→//! Uses a mock UploadHandler that can be configured to succeed or fail.
  4→
  5→#[cfg(test)]
  6→mod write_queue_tests {
  7→    use std::sync::atomic::{AtomicU32, Ordering};
  8→    use std::sync::Arc;
  9→    use std::time::Instant;
 10→
 11→    use crate::sync::queue::{QueuedWrite, UploadHandler, WriteQueue};
 12→
 13→    // ── Mock Upload Handler ──────────────────────────────────────────────
 14→
 15→    /// Mock handler that always succeeds.
 16→    struct SuccessHandler {
 17→        call_count: AtomicU32,
 18→    }
 19→
 20→    impl SuccessHandler {
 21→        fn new() -> Self {
 22→            Self {
 23→                call_count: AtomicU32::new(0),
 24→            }
 25→        }
 26→
 27→        fn calls(&self) -> u32 {
 28→            self.call_count.load(Ordering::SeqCst)
 29→        }
 30→    }
 31→
 32→    impl UploadHandler for SuccessHandler {
 33→        async fn upload_and_register(
 34→            &self,
 35→            _write: &QueuedWrite,
 36→        ) -> Result<(), String> {
 37→            self.call_count.fetch_add(1, Ordering::SeqCst);
 38→            Ok(())
 39→        }
 40→    }
 41→
 42→    /// Mock handler that always fails with a configurable message.
 43→    struct FailHandler;
 44→
 45→    impl UploadHandler for FailHandler {
 46→        async fn upload_and_register(
 47→            &self,
 48→            _write: &QueuedWrite,
 49→        ) -> Result<(), String> {
 50→            Err("network unreachable".to_string())
 51→        }
 52→    }
 53→
 54→    /// Mock handler that tracks the order of processed filenames.
 55→    struct OrderTracker {
 56→        order: std::sync::Mutex<Vec<String>>,
 57→    }
 58→
 59→    impl OrderTracker {
 60→        fn new() -> Self {
 61→            Self {
 62→                order: std::sync::Mutex::new(Vec::new()),
 63→            }
 64→        }
 65→
 66→        fn processed_order(&self) -> Vec<String> {
 67→            self.order.lock().unwrap().clone()
 68→        }
 69→    }
 70→
 71→    impl UploadHandler for OrderTracker {
 72→        async fn upload_and_register(
 73→            &self,
 74→            write: &QueuedWrite,
 75→        ) -> Result<(), String> {
 76→            self.order.lock().unwrap().push(write.filename.clone());
 77→            Ok(())
 78→        }
 79→    }
 80→
 81→    // ── Helpers ──────────────────────────────────────────────────────────
 82→
 83→    fn make_write(id: &str, filename: &str) -> QueuedWrite {
 84→        QueuedWrite {
 85→            id: id.to_string(),
 86→            parent_ino: 1,
 87→            encrypted_content: vec![0xDE, 0xAD],
 88→            encrypted_file_key: vec![0xBE, 0xEF],
 89→            iv: vec![0x00; 12],
 90→            filename: filename.to_string(),
 91→            created_at: Instant::now(),
 92→            retries: 0,
 93→        }
 94→    }
 95→
 96→    // ── Tests ────────────────────────────────────────────────────────────
 97→
 98→    #[tokio::test]
 99→    async fn test_write_queue_enqueue_and_len() {
100→        let mut queue = WriteQueue::new(5);
101→        assert_eq!(queue.len(), 0);
102→        assert!(queue.is_empty());
103→
104→        queue.enqueue(make_write("1", "a.txt"));
105→        assert_eq!(queue.len(), 1);
106→        assert!(!queue.is_empty());
107→
108→        queue.enqueue(make_write("2", "b.txt"));
109→        assert_eq!(queue.len(), 2);
110→
111→        queue.enqueue(make_write("3", "c.txt"));
112→        assert_eq!(queue.len(), 3);
113→    }
114→
115→    #[tokio::test]
116→    async fn test_write_queue_process_success() {
117→        let mut queue = WriteQueue::new(5);
118→        queue.enqueue(make_write("1", "a.txt"));
119→        queue.enqueue(make_write("2", "b.txt"));
120→
121→        let handler = SuccessHandler::new();
122→        let processed = queue.process(&handler).await.unwrap();
123→
124→        assert_eq!(processed, 2);
125→        assert_eq!(handler.calls(), 2);
126→        assert!(queue.is_empty());
127→    }
128→
129→    #[tokio::test]
130→    async fn test_write_queue_process_failure_retries() {
131→        let mut queue = WriteQueue::new(3); // max 3 retries
132→        queue.enqueue(make_write("1", "failing.txt"));
133→
134→        let handler = FailHandler;
135→
136→        // First process: item fails, retries=1, moved to back
137→        let processed = queue.process(&handler).await.unwrap();
138→        assert_eq!(processed, 0);
139→        assert_eq!(queue.len(), 1); // Still in queue
140→
141→        // Second process: retries=2
142→        let _ = queue.process(&handler).await;
143→        assert_eq!(queue.len(), 1);
144→
145→        // Third process: retries=3
146→        let _ = queue.process(&handler).await;
147→        assert_eq!(queue.len(), 1);
148→
149→        // Fourth process: retries=4 > max_retries=3, item dropped
150→        let _ = queue.process(&handler).await;
151→        assert_eq!(queue.len(), 0);
152→        assert!(queue.is_empty());
153→    }
154→
155→    #[tokio::test]
156→    async fn test_write_queue_fifo_order() {
157→        let mut queue = WriteQueue::new(5);
158→        queue.enqueue(make_write("1", "first.txt"));
159→        queue.enqueue(make_write("2", "second.txt"));
160→        queue.enqueue(make_write("3", "third.txt"));
161→
162→        let tracker = OrderTracker::new();
163→        let processed = queue.process(&tracker).await.unwrap();
164→
165→        assert_eq!(processed, 3);
166→        assert_eq!(
167→            tracker.processed_order(),
168→            vec!["first.txt", "second.txt", "third.txt"]
169→        );
170→    }
171→
172→    #[tokio::test]
173→    async fn test_write_queue_is_empty() {
174→        let mut queue = WriteQueue::new(5);
175→
176→        // Empty on init
177→        assert!(queue.is_empty());
178→
179→        // Non-empty after enqueue
180→        queue.enqueue(make_write("1", "test.txt"));
181→        assert!(!queue.is_empty());
182→
183→        // Empty after successful process
184→        let handler = SuccessHandler::new();
185→        let _ = queue.process(&handler).await;
186→        assert!(queue.is_empty());
187→    }
188→
189→    #[tokio::test]
190→    async fn test_write_queue_process_empty_returns_zero() {
191→        let mut queue = WriteQueue::new(5);
192→        let handler = SuccessHandler::new();
193→        let processed = queue.process(&handler).await.unwrap();
194→        assert_eq!(processed, 0);
195→        assert_eq!(handler.calls(), 0);
196→    }
197→
198→    #[tokio::test]
199→    async fn test_write_queue_default_max_retries() {
200→        let queue = WriteQueue::default();
201→        assert!(queue.is_empty());
202→        // Default max_retries is 5 -- we verify by creating with default
203→        // and checking an item gets 5 retries before drop
204→        let mut queue = WriteQueue::default();
205→        queue.enqueue(make_write("1", "test.txt"));
206→
207→        let handler = FailHandler;
208→        for _ in 0..5 {
209→            let _ = queue.process(&handler).await;
210→            assert_eq!(queue.len(), 1, "Item should remain in queue within max_retries");
211→        }
212→        // 6th failure: retries=6 > max_retries=5, dropped
213→        let _ = queue.process(&handler).await;
214→        assert!(queue.is_empty(), "Item should be dropped after exceeding max_retries");
215→    }
216→}
