142→/// Generate a random UUID v4 string.
143→fn generate_uuid_v4() -> String {
144→    let bytes = crypto::utils::generate_random_bytes(16);
145→    format!(
146→        "{:02x}{:02x}{:02x}{:02x}-{:02x}{:02x}-4{:01x}{:02x}-{:02x}{:02x}-{:02x}{:02x}{:02x}{:02x}{:02x}{:02x}",
147→        bytes[0], bytes[1], bytes[2], bytes[3],
148→        bytes[4], bytes[5],
149→        bytes[6] & 0x0f, bytes[7],
150→        (bytes[8] & 0x3f) | 0x80, bytes[9],
151→        bytes[10], bytes[11], bytes[12], bytes[13], bytes[14], bytes[15],
152→    )
153→}
